\centering
\small
\resizebox{\columnwidth}{!}{%
\begin{tabular}{llcccc}
\toprule
\textbf{Embedding} & \textbf{Control} & \textbf{Raw $\rho$} & \textbf{Raw $p$} & \textbf{Partial $r$} & \textbf{Partial $p$} \\
\midrule
MiniLM & --- & $+$0.208 & $0.011$ & --- & --- \\
MiniLM & log freq & --- & --- & $+$0.133 & $0.11$ \\
MiniLM & log freq $+$ degree & --- & --- & --- & $0.23$ \\
\midrule
